const body = $json.body ?? $json;
const required = ['orderId', 'email', 'amount'];
const missing = required.filter((key) => body[key] === undefined || body[key] === null || body[key] === '');
const validEmail = typeof body.email === 'string' && /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(body.email);
const validAmount = Number.isFinite(Number(body.amount)) && Number(body.amount) > 0;
return [{ json: { ok: missing.length === 0 && validEmail && validAmount, route: missing.length === 0 && validEmail && validAmount ? 'accepted' : 'rejected', requestId: `demo-${Date.now()}`, errors: [...missing.map((key) => `missing:${key}`), ...(!validEmail ? ['invalid:email'] : []), ...(!validAmount ? ['invalid:amount'] : [])], data: body } }];
